import {fixture as f,commitments,money as m,total,analyze,transition} from './model.mjs';
const app=document.querySelector('#app');let plan={state:'INITIAL',contribution:8000,date:'Nov 08',previous:null};let draft={amount:12000,item:'New phone',when:'This week'};let setupStep=1;let notice='';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(label,route,cls='btn')=>`<a class="${cls}" href="#/${route}">${label}</a>`;
const button=(label,action,cls='btn')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
const row=(label,value)=>`<div class="row"><span>${label}</span><strong class="num">${value}</strong></div>`;
const bar=()=>`<div class="bar" role="img" aria-label="Available ₹42,800: committed ₹26,700 and flexible ₹16,100"><span></span><span></span></div><div class="legend"><span><i class="dot"></i>Already committed</span><span><i class="dot light"></i>Flexible before goals</span></div>`;
const protectedList=covered=>`<div class="protected-line"><div class="eyebrow">${covered?'Remains protected':'Protected money stays separate'}</div><div class="protected-list">${(covered?['Rent','Utilities','Internet + mobile','Subscriptions','SIP','Emergency fund']:['Emergency fund — untouched']).map(x=>`<span>✓ ${x}</span>`).join('')}</div></div>`;
function header(landing=false){return `<header class="header"><a class="brand" href="#/${landing?'':'home'}" aria-label="NIVA home"><span class="mark" aria-hidden="true"></span>NIVA</a><nav aria-label="Main navigation">${landing?`<span class="muted">A little clarity. A little breathing room.</span>${link('Explore demo','home','btn secondary')}`:`<span class="muted">Your month</span><span class="profile"><span class="avatar" aria-hidden="true">A</span>Aanya</span>`}</nav></header>`;}
const footer=()=>`<footer class="footer"><span>NIVA · Know what a purchase changes.</span><span>Portfolio concept · Local planning only · No bank connection</span></footer>`;
function landing(){return `${header(true)}<main id="main" class="fade"><section class="hero"><div><div class="eyebrow">Financial clarity, before the decision</div><h1>Money decisions,<br>with the rest of<br>the month in view.</h1><p>See how a purchase affects your commitments, goals and financial breathing room before you decide.</p><div class="actions">${link('See my month →','signup')}${link('Explore demo','home','text-btn')}</div><p class="hero-note">No account needed to explore. No financial judgment.</p></div><div class="visual"><div class="visual-head"><span class="eyebrow">October, in perspective</span><span class="tag">Your month</span></div><p class="muted">Flexible before goals</p><div class="big num">₹16,100</div><p class="muted">Some money is already spoken for.<br>This is the part you can plan around.</p>${bar()}${row('Available now','₹42,800')}${row('Upcoming commitments','₹26,700')}<div class="visual-note"><span class="eyebrow">A decision, with context</span>${row('New phone','₹12,000')}<p class="muted">What stays protected? What would shift?</p></div></div></section><section class="intro-strip"><div><div class="eyebrow">01 / Understand</div><h2>See the whole month.</h2><p>Your available balance, commitments and preferences, clearly separated.</p></div><div><div class="eyebrow">02 / Explore</div><h2>Make room for a what-if.</h2><p>See a purchase’s consequences before changing anything.</p></div><div><div class="eyebrow">03 / Decide</div><h2>The choice stays yours.</h2><p>Keep your plan, explore an adjustment, or try another amount.</p></div></section></main>${footer()}`;}
function home(){return `${header()}<main id="main" class="fade"><div class="page-heading"><div><div class="eyebrow">Your October overview</div><h1>A little perspective, Aanya.</h1></div><span class="month">October 2026</span></div>${notice?`<div class="notice"><div><strong>${notice}</strong><p>${plan.previous?`Your October Goa contribution is now ${m(plan.contribution)}. Planning only; no money moved.`:'Your balance and protected commitments haven’t changed.'}</p></div>${plan.previous?button('Undo','undo','text-btn'):''}</div>`:''}<div class="home-grid"><div><section class="hero-money"><div class="eyebrow">Flexible before goals</div><div class="big num">₹16,100</div><p>After ₹26,700 of upcoming commitments.</p><p class="muted">Planned goal contributions are separate.</p><details><summary>How is this calculated?</summary><p>₹42,800 available − ₹26,700 committed = ₹16,100 flexible. Your Goa plan and preferred buffer have not been deducted.</p></details></section><section class="question">${link('Can I afford something? <span aria-hidden="true">↗</span>','purchase','btn blue')}<p>See what a purchase would change before you decide.</p></section><section class="section"><div class="section-title"><h2>Where your money stands</h2></div>${bar()}${row('Available now','₹42,800')}${row('Already committed','₹26,700')}${row('Flexible before goals','₹16,100')}<div class="row"><span>Preferred month-end buffer<br><small class="muted">A preference, not a commitment</small></span><strong class="num">₹7,000</strong></div><div class="row"><span>Planned Goa contribution<br><small class="muted">Optional allocation from flexible money</small></span><strong class="num">${m(plan.contribution)}</strong></div><p class="muted">After the Goa plan: ${m(16100-plan.contribution)}. After also setting aside your preferred buffer: ${m(16100-plan.contribution-7000)}.</p></section></div><aside class="support"><section class="section"><div class="section-title"><h2>Already spoken for</h2><span class="muted">Coming up</span></div>${commitments.filter(c=>['05','08','12'].includes(c.date)).map(c=>`<div class="commitment"><span class="date">OCT<b>${c.date}</b></span><span>${c.name}</span><strong class="num">${m(c.amount)}</strong></div>`).join('')}<details class="muted" style="margin-top:14px"><summary>All five commitments · ₹26,700</summary>${commitments.map(c=>row(c.name,m(c.amount))).join('')}</details></section><section class="section"><div class="section-title"><h2>A little closer to Goa</h2><span class="muted">Savings goal</span></div><div class="goal-number num">₹18,000 <small>of ₹30,000</small></div><div class="progress" role="img" aria-label="Goa goal: 60 percent saved"><span></span></div><p class="muted">60% saved</p>${row('Planned this month',m(plan.contribution))}${row('Estimated completion',plan.date)}<p class="muted">Illustrative estimate based on your current plan.</p></section><div class="protected-box"><div><strong>Emergency fund</strong><p class="muted">₹96,000 of ₹1,50,000</p></div><span class="tag">✓ Protected</span></div></aside></div></main>${footer()}`;}
function signup(){return `${header(true)}<main id="main" class="narrow fade"><form id="signup" class="form-panel"><div class="eyebrow">A clearer starting point</div><h1>Make room for clarity.</h1><p>Create a local demo account. Use sample details; nothing is sent to a server.</p><label for="name">Name</label><input id="name" name="name" autocomplete="given-name" value="Aanya" required><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="aanya@example.com" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="new-password" minlength="8" required aria-describedby="password-help"><small id="password-help" class="muted">At least 8 characters. Password is never saved.</small><div class="actions"><button class="btn" type="submit">Create account →</button></div><p style="margin:22px 0 0">Already have an account? ${button('Log in','login','text-btn')}</p></form></main>${footer()}`;}
function setup(){let content=setupStep===1?`<h1>Let’s understand your month.</h1><p>Start with the money available for October.</p><label for="income">Monthly take-home income</label><input id="income" value="₹85,000" readonly><label for="balance">Available balance</label><input id="balance" value="₹42,800" readonly><p class="muted" style="margin-top:18px">This concept uses Aanya’s October fixture to keep every scenario consistent.</p>`:setupStep===2?`<h1>What’s already spoken for?</h1><p>Review your remaining commitments.</p>${commitments.map((c,i)=>`<label for="c${i}">${c.name}</label><div class="input-money"><span>₹</span><input id="c${i}" name="c${i}" type="number" min="0" required value="${c.amount}"></div>`).join('')}<div id="commitment-total">${row('Total',m(total))}</div><p class="muted">You can edit these to explore the total. The signature demo uses the original ₹26,700 fixture.</p>`:`<h1>What do you want to protect?</h1><p>Separate essentials from the preferences you can adjust.</p>${row('Emergency fund','₹96,000 · Protected')}${row('Preferred month-end buffer','₹7,000')}<p class="muted">Your buffer is an amount you prefer to keep, not a mandatory bill.</p>${row('Goa · planned this month','₹8,000')}<p class="muted">Goal contributions are optional. Your emergency fund is excluded from purchase scenarios.</p>`;return `${header(true)}<main id="main" class="narrow fade"><form id="setup" class="form-panel"><div class="steps" aria-label="Step ${setupStep} of 3">${[1,2,3].map(n=>`<span class="${n<=setupStep?'active':''}"></span>`).join('')}</div><div class="eyebrow">Step ${setupStep} of 3</div>${content}<div class="actions">${setupStep>1?button('Back','setup-back','btn secondary'):''}<button type="submit" class="btn">${setupStep===3?'See my month →':'Continue →'}</button></div></form></main>${footer()}`;}
function purchase(){plan=transition(plan,'SCENARIO_DRAFT');return `${header()}<main id="main" class="narrow fade">${link('← Back to my month','home','back')}<form id="purchase" class="form-panel"><div class="eyebrow">Explore a purchase</div><h1>What are you thinking about?</h1><p>A what-if for your month. No purchase is made.</p><label for="amount">Amount</label><div class="input-money"><span>₹</span><input id="amount" name="amount" type="number" min="1" max="10000000" step="1" value="${draft.amount}" required aria-describedby="amount-error"></div><div id="amount-error" class="error"></div><label for="item">What is it?</label><input id="item" name="item" value="${esc(draft.item)}" maxlength="60" required><label for="when">When?</label><select id="when" name="when"><option ${draft.when==='This week'?'selected':''}>This week</option><option ${draft.when==='Later this month'?'selected':''}>Later this month</option></select><div class="actions"><button type="submit" class="btn blue">Check the impact →</button>${link('Cancel','home','text-btn')}</div></form></main>${footer()}`;}
function comparison(s){return `<section class="comparison" aria-label="Before and after the hypothetical purchase"><div class="comparison-head"><span>Monthly picture</span><span>Before</span><span>After purchase</span></div>${[['Available balance',42800,s.available],['Hard commitments',26700,26700],['Flexible before goals',16100,s.after]].map((x,i)=>`<div class="comparison-row ${i===2?'highlight':''}"><span>${x[0]}</span><span class="num">${m(x[1])}</span><span class="num">${m(x[2])}</span></div>`).join('')}</section>`;}
function scenario(){const s=analyze(draft.amount);return `${header()}<main id="main" class="flow fade">${link('← Your month','home','back')}<div class="flow-header"><p class="purchase-label"><strong class="num">${m(draft.amount)}</strong> · ${esc(draft.item)} · ${esc(draft.when)}</p><h1>Here’s what ${m(draft.amount)}<br>would change.</h1><p>A view of the consequences. The decision stays yours.</p></div>${protectedList(s.covered)}${comparison(s)}<div class="tradeoff"><div><h2>${s.covered?'Your preferred breathing room':'The scenario exceeds flexible money'}</h2><p>${s.gap?`The purchase would leave your flexible money ${m(s.gap)} below the ₹7,000 buffer you prefer to keep.`:'Your flexible remainder meets your preferred ₹7,000 buffer, before planned goal contributions.'}</p><p>Preferred: ₹7,000 · After purchase: ${m(s.after)}</p></div><div><div class="eyebrow">${s.gap?'Buffer gap':'Above preference'}</div><div class="gap num">${s.gap?'−'+m(s.gap):m(s.after-7000)}</div></div></div><section class="option"><div class="eyebrow">Optional plan adjustment</div><h2>One way to ease the goal allocation</h2>${row('October Goa contribution',`${m(plan.contribution)} → ${m(s.proposed)}`)}${row('Estimated completion',`${plan.date} → ${s.proposed===8000?'Nov 08':s.proposed===5100?'Nov 20':'Later than Nov 08'}`)}<p>Reducing the original ₹8,000 Goa plan by ${m(s.released)} releases that amount from your goal allocation.</p><div class="explanation"><strong>Cash and plans are different.</strong> The ${m(s.after)} cash remainder already excludes the purchase and commitments, but does not deduct Goa. Reducing a future contribution cannot increase it to ₹7,000.${s.amount===12000?' The ₹5,100 option reallocates ₹2,900; the cash buffer gap remains ₹2,900.':''}<br>After this proposed Goa contribution, cash remaining would be ${m(s.after-s.proposed)}. ${s.after-s.proposed<0?'The purchase and goal contribution cannot both be funded from this balance.':''}</div></section><section class="decision"><div class="actions">${button('Adjust my plan','preview','btn secondary')}${button('Keep my current plan','keep','btn secondary')}${link('Try another amount','purchase','btn secondary')}</div><p>Nothing changes until you review and apply. This scenario never executes a payment.</p></section></main>${footer()}`;}
function preview(){const s=analyze(draft.amount);return `${header()}<main id="main" class="flow fade">${link('← Back to the impact','scenario','back')}<div class="flow-header"><span class="preview-tag">PREVIEW</span><h1>Shift the goal.<br>Keep the decision yours.</h1><p>Your plan hasn’t changed yet.</p></div><div class="preview-summary"><div class="eyebrow">Hypothetical purchase</div>${row(esc(draft.item),m(draft.amount))}<h2 style="margin-top:22px">Current plan → Proposed plan</h2>${row('October Goa contribution',`${m(plan.contribution)} → ${m(s.proposed)}`)}${row('Contribution change',m(s.proposed-plan.contribution))}${row('Estimated completion',`${plan.date} → ${s.proposed===8000?'Nov 08':s.proposed===5100?'Nov 20':'Later than Nov 08'}`)}${row('Preferred buffer','₹7,000 · unchanged')}${row('Cash after hypothetical purchase',m(s.after))}${row('Cash after purchase + proposed Goa',m(s.after-s.proposed))}${row('Essentials + emergency fund','No change')}</div><p class="preview-footnote">This changes a planned contribution only. It does not restore cash, make a purchase, or transfer money. Completion dates are illustrative estimates.</p><div class="decision"><div class="actions">${button('Apply adjustment','apply','btn blue')}${link('Cancel','scenario','btn secondary')}</div></div></main>${footer()}`;}
function render(){const route=location.hash.replace('#/','')||'';const pages={'':landing,home,signup,setup,purchase,scenario,preview};app.innerHTML=`<div class="wrap">${(pages[route]||landing)()}</div>`;document.title=`NIVA — ${({'':'Money decisions, in perspective',home:'Your October',signup:'Create account',setup:'Financial setup',purchase:'Explore a purchase',scenario:'Purchase impact',preview:'Adjustment preview'})[route]||'Your month'}`;}
function go(route){if(location.hash===`#/${route}`)render();else location.hash=`/${route}`;}
function say(text){document.querySelector('#status').textContent=text;setTimeout(()=>{document.querySelector('#status').textContent=''},6000);}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}});
app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='preview'){plan={...transition(plan,'ADJUSTMENT_PREVIEW'),proposed:analyze(draft.amount).proposed};go('preview');}if(action==='apply'){plan=transition(plan,'APPLY');notice='Plan updated.';go('home');say('Plan updated. Undo is available.');}if(action==='undo'){plan=transition(plan,'UNDO');notice='Adjustment undone.';render();say('Adjustment undone. Goa contribution restored.');}if(action==='keep'){notice='No changes made.';go('home');say('No changes made. Your current plan is unchanged.');}if(action==='setup-back'){setupStep--;render();}if(action==='login'){say('Local demo: opening Aanya’s month. No sign-in required.');go('home');}});
app.addEventListener('input',e=>{if(e.target.name?.startsWith('c')&&document.querySelector('#commitment-total')){const sum=[...document.querySelectorAll('#setup input')].reduce((n,i)=>n+Number(i.value),0);document.querySelector('#commitment-total').innerHTML=row('Total',m(sum));}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='signup'){setupStep=1;go('setup');}if(e.target.id==='setup'){if(setupStep<3){setupStep++;render();window.scrollTo(0,0);}else go('home');}if(e.target.id==='purchase'){const data=new FormData(e.target);const amount=Number(data.get('amount'));if(!Number.isInteger(amount)||amount<=0){document.querySelector('#amount-error').textContent='Enter a whole-rupee amount greater than zero.';return;}draft={amount,item:data.get('item').trim()||'Purchase',when:data.get('when')};plan=transition(plan,'SCENARIO_ANALYZED');go('scenario');}});
render();
